  INDEX `idx_cw_character`(`character_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1378 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '角色武器推荐' ROW_FORMAT = DYNAMIC;

