-- ----------------------------
-- Table structure for t_weapon
-- ----------------------------
DROP TABLE IF EXISTS `t_weapon`;
CREATE TABLE `t_weapon`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '武器名',
  `rarity` tinyint NOT NULL DEFAULT 5 COMMENT '星级',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型: 单手剑/双手剑/长柄武器/法器/弓',
  `stat` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '副属性',
  `atk1` int NULL DEFAULT NULL COMMENT '1级基础攻击力(白值)',
  `atk90` int NULL DEFAULT NULL COMMENT '90级基础攻击力(白值)',
  `sub_stat` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '副词条名称',
  `sub_value` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '副词条90级提升值(带单位)',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '武器效果描述',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 1-显示 0-隐藏',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_weapon_name`(`name` ASC) USING BTREE,
  INDEX `idx_weapon_type`(`type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 606 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '武器养成攻略' ROW_FORMAT = DYNAMIC;

