INSERT INTO `t_artifact_set` VALUES (5, '被怜爱的少女', 5, '治疗', '蒙德', '角色受到的治疗效果+15%', '施放元素战技或元素爆发后的10秒内，队伍中所有角色受治疗效果+20%', '治疗辅助', '/artifacts/beilianai-shaonv.png', '#7fd4a8', 5, 1, '2026-11-10 00:00:46', '2026-11-10 00:00:46');
