INSERT INTO `t_artifact_set` VALUES (8, '冰风迷途的勇士', 5, '冰', '龙脊雪山', '冰元素伤害加成+15%', '攻击处于冰元素影响下的敌人时暴击率+20%；若敌人处于冻结状态，暴击率额外+20%', '永冻冰C', '/artifacts/bingfeng-mitu-yongshi.png', '#6fc7e8', 8, 1, '2026-11-10 00:00:46', '2026-11-10 00:00:46');
INSERT INTO `t_artifact_set` VALUES (9, '沉沦之心', 5, '水', '龙脊雪山', '水元素伤害加成+15%', '施放元素战技后的15秒内，普通攻击与重击造成的伤害+30%', '水系站场主C', '/artifacts/chenlun-zhixin.png', '#4f9de0', 9, 1, '2026-11-10 00:00:46', '2026-11-10 00:00:46');
