INSERT INTO `t_artifact_set` VALUES (12, '悠古的磐岩', 5, '岩', '璃月', '岩元素伤害加成+15%', '获得结晶反应产生的晶片时，队伍中所有角色获得该元素伤害加成+35%，持续10秒', '结晶队辅助', '/artifacts/yougu-de-panyan.png', '#d9a95b', 12, 1, '2026-11-10 00:00:46', '2026-11-10 00:00:46');
