INSERT INTO `t_artifact_set` VALUES (14, '辰砂往生录', 5, '攻击', '璃月', '攻击力+18%', '施放元素爆发后产生持续16秒的「潜光」效果：攻击力+8%；角色生命值降低时攻击力进一步提升10%，至多4次', '生命波动主C', '/artifacts/chensha-wangshenglu.png', '#e08a6a', 14, 1, '2026-11-10 00:00:46', '2026-11-10 00:00:46');
