INSERT INTO `t_artifact_set` VALUES (49, '冒险家', 3, '生命', '多地', '生命值上限+1000', '开启各类宝箱后的5秒内，持续恢复30%生命值', '大世界探索', '/artifacts/maoxianjia.png', '#9fc8a0', 49, 1, '2026-11-10 00:00:46', '2026-11-10 00:00:46');
INSERT INTO `t_artifact_set` VALUES (50, '幸运儿', 3, '防御', '多地', '防御力+100', '拾取摩拉时，恢复300点生命值', '大世界探索', '/artifacts/xingyuner.png', '#b8c090', 50, 1, '2026-11-10 00:00:46', '2026-11-10 00:00:46');
INSERT INTO `t_artifact_set` VALUES (51, '游医', 3, '治疗', '多地', '角色受到的治疗效果+20%', '施放元素爆发时，恢复20%生命值', '大世界探索', '/artifacts/youyi.png', '#8fc8b0', 51, 1, '2026-11-10 00:00:46', '2026-11-10 00:00:46');
INSERT INTO `t_artifact_set` VALUES (52, '纺月的夜歌', 5, '充能', '挪德卡莱', '元素充能效率+20%', '造成元素伤害时，获得持续8秒的「月辉明光·崇信」：队伍月兆为初辉/满辉时，队伍中所有角色的元素精通提高60点/120点；装备者处于后台时也能触发。队伍中每拥有一种不同的「月辉明光」效果，全队触发的月曜反应伤害提升10%，由「月辉明光」产生的效果无法叠加', '6.0 月曜辅助 · 全队精通', '/artifacts/fangyue-de-yege.png', '#a88fd8', 52, 1, '2026-11-10 00:00:46', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (53, '穹境示现之夜', 5, '精通', '挪德卡莱', '元素精通+80', '队伍中附近的角色触发月曜反应时，若装备者在场上，将获得持续4秒的「月辉明光·蓄念」：队伍月兆为初辉/满辉时，暴击率提升15%/30%。队伍中每拥有一种不同的「月辉明光」效果，全队触发的月曜反应伤害提升10%，由「月辉明光」产生的效果无法叠加', '6.0 月曜主C · 暴击', '/artifacts/qiongjing-shixian-zhiye.png', '#8f9fd8', 53, 1, '2026-11-10 00:00:46', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (54, '晨星与月的晓歌', 5, '精通', '挪德卡莱', '元素精通+80', '装备者处于队伍后台时，造成的月曜反应伤害提升20%；队伍的月兆等级至少为满辉时，造成的月曜反应伤害进一步提升40%。上述效果将在装备者位于场上3秒后移除', '6.3 月曜后台副C', '/artifacts/chenxing-yuyue-de-xiaoge.png', '#a8b0e0', 54, 1, '2026-11-10 00:00:46', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (55, '风起之日', 5, '攻击', '挪德卡莱', '攻击力+18%', '普通攻击、重击、元素战技或元素爆发命中敌人后，将获得持续6秒的「风与牧歌的眷怜」：攻击力提高25%。若装备者已完成「魔女的课业」，该效果升级为「风与牧歌的决意」，额外使暴击率提升20%。装备者处于后台时也能触发', '6.3 攻击增伤 · 魔女课业', '/artifacts/fengqi-zhi-ri.png', '#8fc8b0', 55, 1, '2026-11-10 00:00:46', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (56, '染血的骑士道', 5, '物理', '蒙德', '物理伤害加成+25%', '击败敌人后的10秒内，施放重击不消耗体力，且重击造成的伤害+50%', '物理重击主C', '/artifacts/ranxue-de-qishidao.png', '#b8564f', 56, 1, '2026-11-11 23:25:37', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (57, '渡过烈火的贤人', 5, '火', '蒙德', '火元素抗性+40%', '对处于火元素影响下的敌人造成的伤害+35%', '火伤抗性对策', '/artifacts/duguo-liehuo-de-xianren.png', '#e08a52', 57, 1, '2026-11-11 23:25:37', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (58, '未竟的遐思', 5, '燃烧', '枫丹', '攻击力+18%', '脱离战斗状态3秒后，造成的伤害提升50%；战斗状态下附近不存在燃烧状态的敌人超过6秒后，该增伤每秒降低10%直至0；存在燃烧状态的敌人时每秒提升10%直至50%。装备者处于后台时依然会触发', '4.6 燃烧体系 · 持续增伤', '/artifacts/weijing-de-xiasi.png', '#d0a35e', 58, 1, '2026-11-11 23:25:37', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (59, '长夜之誓', 5, '下落攻击', '纳塔', '下落攻击造成的伤害+25%', '装备者的下落攻击/重击/元素战技命中敌人后，分别获得1/2/2层「永照的流辉」，各类型每1秒至多触发一次；每层使下落攻击伤害+15%，持续6秒，最多叠加5层，每层持续时间独立计算', '5.5 下落攻击主C', '/artifacts/changye-zhishi.png', '#9a8fd0', 59, 1, '2026-11-11 23:25:37', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (60, '深廊终曲', 5, '冰', '纳塔', '冰元素伤害加成+15%', '装备者元素能量为0时，普通攻击与元素爆发造成的伤害+60%；普攻造成伤害后元素爆发增伤失效6秒，元素爆发造成伤害后普攻增伤失效6秒。角色处于队伍后台时也能触发', '5.5 无能量冰C · 丝柯克', '/artifacts/shenlang-zhongqu.png', '#7fb8d8', 60, 1, '2026-11-11 23:25:37', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (61, '天之美赐', 5, '辅助', '蒙德', '元素充能效率+20%', '若装备者已完成「魔女的课业」，施放元素战技后获得「天光之引」：依据装备者元素类型，使队伍中附近所有角色获得20%对应元素伤害加成，持续20秒，后台亦可触发；队伍拥有「魔导·秘仪」时升级为「凡世颂歌」，加成提升至40%并额外覆盖当前场上角色元素类型，同名套装产生的加成无法叠加', '6.7 全队元素增伤辅助', '/artifacts/tian-zhi-meici.png', '#e0c878', 61, 1, '2026-11-11 23:25:37', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (62, '影中沉凝的幻灭', 5, '超导', '蒙德', '攻击力+18%', '超导反应造成的伤害+80%；装备者攻击受到超导反应影响的敌人时，本次攻击的暴击率+16%', '6.7 超导物伤体系', '/artifacts/yingzhong-chenning-de-huanmie.png', '#7f7fb0', 62, 1, '2026-11-11 23:25:37', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (63, '血红之证', 5, '星扩散', '至冬', '攻击力+18%', '装备者触发星扩散反应后的10秒内，暴击率+16%，星扩散反应伤害+40%', '7.0 星扩散站场主C', '/artifacts/xuehong-zhi-zheng.png', '#c0454f', 63, 1, '2026-11-11 23:25:37', '2026-11-11 23:25:37');
INSERT INTO `t_artifact_set` VALUES (64, '炉火融炼之心', 5, '星烁', '至冬', '攻击力+18%', '装备者触发星烁反应或造成星烁反应伤害后的12秒内，攻击力+12%，队伍中附近所有角色造成的星烁反应伤害+50%；装备者处于后台时也能触发，同名套装产生的伤害加成无法叠加', '7.0 全队星烁反应辅助', '/artifacts/luhuo-ronglian-zhi-xin.png', '#d87050', 64, 1, '2026-11-11 23:25:37', '2026-11-11 23:25:37');
