INSERT INTO `t_team` VALUES (1, '胡桃蒸发队', '重击蒸发 · 高额单体爆发', '行秋+夜兰双水挂水 → 钟离开盾减抗 → 胡桃 E 后重击蒸发，双水共鸣提升生命与充能。', 0, 1, '2026-11-02 09:46:00', '2026-11-10 00:39:20');
INSERT INTO `t_team` VALUES (2, '迪卢克融化队', '融化蒸发 · 火系站场', '班尼特 Q 加攻 → 万叶扩散减抗 → 行秋挂水 → 迪卢克 E+Q 三段融化蒸发。', 1, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (3, '可莉蒸发队', '站场蒸发 · 诡雷输出', '双水挂水 → 班尼特加攻 → 可莉重击与诡雷稳定蒸发，双火共鸣加攻。', 2, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (4, '宵宫蒸发队', '普攻蒸发 · 对单极强', '钟离开盾保站场 → 行秋+夜兰双水挂水 → 宵宫 E 附魔普攻连射蒸发。', 3, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (5, '林尼纯火队', '蓄力箭 · 纯火叠层', '三火共鸣加攻 → 万叶减抗 → 班尼特加攻 → 林尼蓄力箭+猫猫弹叠层输出。', 4, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (6, '阿蕾奇诺蒸发队', '战技叠层 · 蒸发爆发', '班尼特加攻 → 双水挂水 → 阿蕾奇诺 E 叠层后重击蒸发爆发。', 5, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (7, '玛薇卡战舰', '火神爆发 · 纳塔体系', '希诺宁减抗 → 茜特菈莉挂冰 → 班尼特加攻 → 玛薇卡 Q 战意爆发收割，危战最优解。', 6, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (8, '杜林双魔导', '风火混伤 · 破盾利器', '6.6 魔导套质变，风火混伤破盾优势大，法尔伽+杜林双核输出，环境适应力强。', 7, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (9, '达达利亚国际队', '断流蒸发 · 万班香体系', '班尼特加攻 → 万叶减抗 → 香菱挂火 → 公子开 E 断流蒸发，经典万达国际队。', 8, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (10, '神里绫人水队', '站场水伤 · 攻速输出', '万叶减抗 → 班尼特加攻 → 夜兰增伤 → 绫人 E 站场水伤连斩，蒸发增伤。', 9, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (11, '那维莱特纯水队', '重击水炮 · 纯色输出', '芙宁娜 Q 增伤 → 万叶扩散减抗 → 心海治疗保层 → 那维莱特重击水炮群伤。', 10, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (12, '玛拉妮蒸发队', '冲浪蒸发 · 高额爆发', '希诺宁减抗 → 班尼特加攻 → 香菱挂火 → 玛拉妮冲浪蒸发爆发。', 11, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (13, '刻晴激化队', '激化 · 高机动输出', '纳西妲挂草 → 菲谢尔后台雷 → 钟离开盾 → 刻晴 E+Q 激化高机动输出。', 12, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (14, '雷电将军爆发队', '雷九万班 · 一刀收割', '九条 E+Q 增攻 → 班尼特 Q 加攻 → 万叶扩散 → 雷神 Q 一刀收割，经典雷九万班。', 13, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
